import{describe,it,expect}from"vitest";import{GANGES_STOPS,getActiveStopIndex,calculateRiverPathProgress,getGangesStats}from"../../frontend/ganges-scrollytelling/ganges-scrollytelling.js";describe("Ganges Scrollytelling Dataset Integrity",()=>{it("contains at least 5 narrative stops along the river (contains 6)",()=>{expect(GANGES_STOPS.length).toBeGreaterThanOrEqual(5),expect(GANGES_STOPS.length).toBe(6)}),it("verifies source-to-sea elevation drop from 4,100m at origin down to 0m at delta",()=>{expect(GANGES_STOPS[0].elevationMeters).toBe(4100),expect(GANGES_STOPS[GANGES_STOPS.length-1].elevationMeters).toBe(0);for(let e=0;e<GANGES_STOPS.length-1;e++)expect(GANGES_STOPS[e].elevationMeters).toBeGreaterThanOrEqual(GANGES_STOPS[e+1].elevationMeters)}),it("verifies monotonic increase of distance from 0 km to 2,525 km",()=>{expect(GANGES_STOPS[0].distanceKm).toBe(0),expect(GANGES_STOPS[GANGES_STOPS.length-1].distanceKm).toBe(2525);for(let e=0;e<GANGES_STOPS.length-1;e++)expect(GANGES_STOPS[e].distanceKm).toBeLessThan(GANGES_STOPS[e+1].distanceKm)}),it("every stop contains required fields and non-empty content",()=>{GANGES_STOPS.forEach((e,t)=>{expect(e,`Stop at index ${t} missing id`).toHaveProperty("id"),expect(e,`Stop at index ${t} missing name`).toHaveProperty("name"),expect(e,`Stop at index ${t} missing location`).toHaveProperty("location"),expect(e,`Stop at index ${t} missing elevation`).toHaveProperty("elevation"),expect(e,`Stop at index ${t} missing distanceKm`).toHaveProperty("distanceKm"),expect(e,`Stop at index ${t} missing summary`).toHaveProperty("summary"),expect(e,`Stop at index ${t} missing details`).toHaveProperty("details"),expect(e,`Stop at index ${t} missing culturalNote`).toHaveProperty("culturalNote"),expect(typeof e.name).toBe("string"),expect(e.name.trim().length).toBeGreaterThan(0),expect(typeof e.summary).toBe("string"),expect(e.summary.trim().length).toBeGreaterThan(0),expect(typeof e.details).toBe("string"),expect(e.details.trim().length).toBeGreaterThan(0)})})}),describe("Active Stop Index Calculation",()=>{const e=[{id:"stop-1",top:0,height:400},{id:"stop-2",top:450,height:400},{id:"stop-3",top:900,height:400},{id:"stop-4",top:1350,height:400},{id:"stop-5",top:1800,height:400},{id:"stop-6",top:2250,height:400}];it("returns index 0 when scroll is near top",()=>{expect(getActiveStopIndex(0,e)).toBe(0)}),it("returns index 2 when scrolled to middle stop",()=>{expect(getActiveStopIndex(1e3,e)).toBe(2)}),it("handles empty offsets array safely",()=>{expect(getActiveStopIndex(100,[])).toBe(0)})}),describe("River Path Progress Math",()=>{it("calculates 0% for origin stop (index 0)",()=>{expect(calculateRiverPathProgress(0,6)).toBe(0)}),it("calculates 60% for middle stop (index 3 of 6 stops)",()=>{expect(calculateRiverPathProgress(3,6)).toBe(60)}),it("calculates 100% for final delta stop (index 5 of 6 stops)",()=>{expect(calculateRiverPathProgress(5,6)).toBe(100)}),it("bounds out-of-range stop indices safely",()=>{expect(calculateRiverPathProgress(10,6)).toBe(100),expect(calculateRiverPathProgress(-2,6)).toBe(0)})}),describe("Ganges River Stats",()=>{it("returns accurate summary statistics for the Ganges River",()=>{const e=getGangesStats(GANGES_STOPS);expect(e.totalStops).toBe(6),expect(e.totalLengthKm).toBe(2525),expect(e.originElevation).toContain("4,100 m"),expect(e.seaElevation).toContain("0 m"),expect(e.statesTraversed).toEqual(["Uttarakhand","Uttar Pradesh","Bihar","Jharkhand","West Bengal"])})});